// Offline evidence compiler for the fixed September 9 sale incident.
// It performs no network or database writes. The actual apply manifest is
// generated by the authenticated Worker preview immediately before apply.
const assert = require('node:assert/strict')
const crypto = require('node:crypto')
const fs = require('node:fs')
const path = require('node:path')

const root = path.join(__dirname, '..', '..')
const evidencePath = path.join(root, 'outputs', 'takeover-20260909', 'sale-zero-items-recovery-current-evidence.json')
const manifestPath = path.join(root, 'outputs', 'takeover-20260909', 'sale-zero-items-recovery-manifest.json')
const sqlPath = path.join(root, 'outputs', 'takeover-20260909', 'sale-zero-items-recovery.sql')
const evidence = JSON.parse(fs.readFileSync(evidencePath, 'utf8'))

assert.equal(evidence.length, 5)
for (const result of evidence) assert.equal(result.success, true)
const [sales, products, lots, effects, amendments] = evidence.map((result) => result.results)
assert.deepEqual(sales.map((row) => Number(row.id)), [16951, 16952, 16953, 16954])
assert.deepEqual(effects.map((row) => Number(row.id)), [16951, 16952, 16953, 16954])
for (const row of effects) {
  assert.equal(Number(row.item_count), 0)
  assert.equal(Number(row.allocation_count), 0)
  assert.equal(Number(row.movement_count), 0)
}
assert.equal(Number(sales.find((row) => Number(row.id) === 16952).delivery_fee_usd), 2.7)
assert.equal(Number(sales.find((row) => Number(row.id) === 16952).delivery_actual_cost_usd), 2.7)
assert.deepEqual(amendments.map((row) => Number(row.id)), [13, 14])

const evidenceSha256 = crypto.createHash('sha256').update(fs.readFileSync(evidencePath)).digest('hex')
const manifest = {
  schema_version: 1,
  generated_at: new Date().toISOString(),
  evidence_sha256: evidenceSha256,
  execution_manifest_source: 'authenticated_no_store_worker_preview',
  target: 'sale-zero-items-20260909-v1',
  confirmation: 'RECOVER SALES 16951 16952 16953',
  proven_sales: [16951, 16952, 16953],
  blocked_sales: [{
    id: 16954,
    receipt_number: '20260909-130228',
    reason: 'sale_time_cost_not_proven',
    evidence: 'current product cost USD 170 matches the pre-sale positive lot cost, but products.updated_at is 2026-09-09T06:11:40.658Z, after the 06:02:29 sale, and no audit/history proves the sale-time product cost',
  }],
  preserved_header_contract: {
    sale_16952: {
      delivery_fee_usd: 2.7,
      delivery_actual_cost_usd: 2.7,
      subtotal_before_usd: 0,
      subtotal_after_usd: 299,
      total_before_usd: 0,
      total_after_usd: 299,
    },
  },
  unknown_line_fields: ['price_mode', 'base_price_usd', 'base_price_khr'],
  proven_numeric_discounts: 0,
  allocation_basis: 'recovery_time_unique_positive_lot_not_historical_proof',
  apply_surface: '/api/system/sale-incident-recovery-20260909/apply',
  atomicity: 'one Worker env.DB.batch guarded by migration 0145 receipt and postconditions',
  raw_sql_apply_allowed: false,
}
fs.writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`)

const sql = `-- READ-ONLY REVIEW QUERIES ONLY. DO NOT EXECUTE A RECOVERY WITH RAW SQL.
-- The write path is /api/system/sale-incident-recovery-20260909/apply because
-- Worker env.DB.batch is the reviewed atomic primitive. Wrangler/D1 REST
-- multi-statement execution is not assumed to have that rollback contract.
SELECT s.id,s.receipt_number,s.sale_status,s.subtotal_usd,s.total_usd,r.revision,
  (SELECT COUNT(*) FROM sale_items i WHERE i.sale_id=s.id) AS item_count,
  (SELECT COUNT(*) FROM inventory_movements m WHERE m.reference_id=s.id AND m.movement_type='sale') AS movement_count
FROM sales s LEFT JOIN sale_write_revisions r ON r.sale_id=s.id
WHERE s.id IN (16951,16952,16953,16954) ORDER BY s.id;

SELECT incident_key,request_digest,actor_id,actor_name,created_at
FROM sale_incident_recovery_receipts
WHERE incident_key='sale-zero-items-20260909-v1';

SELECT operation_id,sale_id,history_id,before_json,after_json
FROM sale_incident_recovery_members ORDER BY sale_id;
`
fs.writeFileSync(sqlPath, sql)
console.log(`PASS wrote evidence manifest ${path.relative(root, manifestPath)} and read-only SQL ${path.relative(root, sqlPath)}`)

